        <input type="text" placeholder="Assignee" @bind="assignee" class="form-input" />
    </div>
    <div class="form-group">
        <select @bind="priority" class="form-input">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="form-group">
        <input type="date" @bind="dueDate" class="form-input" />
    </div>
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@isSaving">Save</button>
        <button class="btn-cancel" @onclick="OnCancel" disabled="@isSaving">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string DefaultStatus { get; set; } = default!;
    [Parameter] public EventCallback<TaskItem> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool isSaving;

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(assignee))
            return;

        isSaving = true;
        try
        {
            var newTask = new TaskItem(0, title.Trim(), assignee.Trim(), priority, dueDate, DefaultStatus);
            await OnSave.InvokeAsync(newTask);
        }
        finally
        {
            isSaving = false;
        }
    }
}

