@using static KanbanColumn.MoveDirection

@* A single Kanban column: header with count, task cards, and add-task toggle *@

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="() => OnMoveTask.InvokeAsync((task, Left))"
                      OnMoveRight="() => OnMoveTask.InvokeAsync((task, Right))"
                      IsMoving="movingTaskId == task.Id" />
        }
    </div>

    <div class="column-footer">
        @if (showAddForm)
        {
            <AddTaskForm DefaultStatus="Status"
                         OnSave="HandleAddTask"
                         OnCancel="() => showAddForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showAddForm = true">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<(TaskItem Task, MoveDirection Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<TaskItem> OnAddTask { get; set; }

    private bool showAddForm;
    private int? movingTaskId;

    private async Task HandleAddTask(TaskItem formData)
    {
        await OnAddTask.InvokeAsync(formData);
        showAddForm = false;
    }

    public enum MoveDirection { Left, Right }
}

